package studio.solocamera;
public final class ScreenRecordingConfigTest {
 public static void main(String[] args){int[][] displays={{1080,2400},{2400,1080},{1080,1920},{1920,1080},{1440,3200},{2208,1840},{480,800},{800,480}};int checks=0;for(int[] display:displays)for(int quality:new int[]{720,1080}){int[] size=ScreenRecordingConfig.size(display[0],display[1],quality);if(size[0]%16!=0||size[1]%16!=0||Math.max(size[0],size[1])>1920||size[0]>display[0]||size[1]>display[1]||Math.min(size[0],size[1])>quality)throw new AssertionError("Invalid output dimensions");double source=display[0]/(double)display[1],result=size[0]/(double)size[1];if(Math.abs(source-result)/source>.025)throw new AssertionError("Aspect ratio changed");int bitrate=ScreenRecordingConfig.bitrate(size[0],size[1]);if(bitrate<2_000_000||bitrate>10_000_000)throw new AssertionError("Unbounded bitrate");checks++;}boolean rejected=false;try{ScreenRecordingConfig.size(0,1920,720);}catch(IllegalArgumentException e){rejected=true;}if(!rejected)throw new AssertionError("Invalid display accepted");System.out.println("PASS "+checks+" portrait/landscape/foldable output configurations; bounded bitrate, dimensions, aspect ratio and invalid display rejection");}
}
